using System.Collections.Generic;
using Godot;

/// <summary>
/// A spot a soldier can take cover at. Generated by <see cref="BoxObstacle.ProvidesCover"/>,
/// or placed by hand. Its -Z axis (<see cref="Facing"/>) points over the cover, towards the threat.
///
/// Cover points disappear when their obstacle is destroyed. If you hold on to one, check
/// <see cref="IsValid"/> before using it.
/// </summary>
public partial class CoverPoint : Node3D
{
    public const string Group = "cover_points";

    /// <summary>Toggled with F4.</summary>
    public static bool ShowMarkers { get; set; }

    /// <summary>
    /// Free slot for your reservation logic. The boilerplate never reads or writes it,
    /// except to color the marker.
    /// </summary>
    public Soldier ReservedBy { get; set; }

    public BoxObstacle Source { get; internal set; }

    public Vector3 Facing => (-GlobalBasis.Z).Flat().Normalized();

    public bool IsValid => IsInstanceValid(this) && IsInsideTree();

    public override void _EnterTree() => AddToGroup(Group);

    public override void _Process(double delta)
    {
        if (!ShowMarkers)
        {
            return;
        }
        bool reserved = IsInstanceValid(ReservedBy) && ReservedBy.IsAlive;
        Color color = reserved ? new Color(1f, 0.8f, 0.2f) : new Color(0.3f, 1f, 0.6f, 0.8f);
        Vector3 p = GlobalPosition + Vector3.Up * 0.05f;
        DebugDraw.Circle(p, 0.25f, color, 12);
        DebugDraw.Line(p, p + Facing * 0.45f, color);
    }

    public static List<CoverPoint> FindInRadius(SceneTree tree, Vector3 position, float radius)
    {
        List<CoverPoint> result = new();
        float radiusSq = radius * radius;
        foreach (Node node in tree.GetNodesInGroup(Group))
        {
            if (node is CoverPoint point && point.GlobalPosition.DistanceSquaredTo(position) <= radiusSq)
            {
                result.Add(point);
            }
        }
        return result;
    }
}
